package solution
import("strconv";"strings")
func DeadlineSequence(s string)(string,bool){p:=strings.Split(s,";");if len(p)!=2||p[1]==""{return "",false};parse:=func(x string)(int,bool){v,e:=strconv.Atoi(x);return v,e==nil&&v>=0&&v<=10000000&&strconv.Itoa(v)==x};n,ok:=parse(p[0]);if !ok{return "",false};o:=[]string{};for _,x:=range strings.Split(p[1],","){v,ok:=parse(x);if !ok||n>10000000-v{return "",false};n+=v;o=append(o,strconv.Itoa(n))};return strings.Join(o,","),true}
